import yaml, re, os, glob
reg = yaml.safe_load(open('governance/check-registry.yaml'))
def s(x): return x if isinstance(x,str) else ' '.join(map(str,x)) if isinstance(x,list) else str(x)
cmds = [s(c.get('cmd','')) for c in reg['checks']] + [s(q.get('cmd','')) for q in reg.get('quarantine',[])]
registered = set()
for c in cmds:
    for m in re.findall(r'(?:scripts|tools)/[\w/]+\.(?:py|sh)', c): registered.add(m)
other_files = glob.glob('.github/workflows/*.yml') + ['scripts/preflight.sh','scripts/regenerate_derived.sh','.claude/settings.json'] + glob.glob('.claude/hooks/*') + glob.glob('skills/**/*.md', recursive=True) + glob.glob('scripts/**/*.py', recursive=True) + glob.glob('scripts/**/*.sh', recursive=True) + glob.glob('tools/*.py')
callers = {}
for f in other_files:
    if '__pycache__' in f or not os.path.isfile(f): continue
    try: t = open(f, encoding='utf-8', errors='replace').read()
    except Exception: continue
    for m in re.findall(r'(?:scripts|tools)/[\w/]+\.(?:py|sh)', t):
        callers.setdefault(m, set()).add(f)
allscripts = [p for p in sorted(set(glob.glob('scripts/**/*.py', recursive=True)+glob.glob('scripts/*.sh')+glob.glob('tools/*.py'))) if '__pycache__' not in p]
print(f"total live scripts: {len(allscripts)}; distinct scripts named in check-registry cmds: {len(registered)}")
print("\n--- scripts NOT named in check-registry cmds:")
for sc in allscripts:
    if sc in registered: continue
    ext = {c for c in callers.get(sc,set()) if os.path.normpath(c)!=os.path.normpath(sc)}
    tag = 'called-by: '+','.join(sorted(ext)[:4]) if ext else '** NO CALLER FOUND **'
    print(f"  {sc:62s} {tag}")
